    {
      "@id": "entity:target-hs_step_1-v1",
      "@type": "prov:Entity",
      "prov:value": "בונה חשבון לתוכנית העימודית שלך והזמן כל אחד מהנערות\n(AddChildAccount)\n\n\"You have {count} child accounts. Would you like to add another?\"\n(CheckForMoreChildren)\n\n\"Please enter a name for the new account.\"\n(EnterNewAccountName)\n\n\"The account has been created successfully!\"\n(CreatedSuccessfully)\n\n\"An error occurred while creating the account.\"\n(ErrorCreatingAccount)\n\n\"This email address is already associated with an existing account. Please sign in instead.\"\n(EmailAlreadyAssociated)\n\n\"Please enter a valid email address.\"\n(InvalidEmailAddress)\n\n\"The password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, one number, and one special character.\"\n(PasswordComplexity)\n\n\"Your password does not meet the complexity requirements.\"\n(IncorrectPasswordComplexity)\n\n\"Please confirm your password.\"\n(ConfirmPassword)\n\n\"The passwords do not match.\"\n(PasswordsDoNotMatch)\n\n\"Account created successfully! You can now sign in.\"\n(AccountCreatedSuccessfully)\n\n\"Sign In\"\n(SignIn)\n\n\"Forgot Password?\"\n(ForgotPassword)\n\n\"Please enter your email address to reset your password.\"\n(EnterEmailForResetPassword)\n\n\"Check your email for instructions on how to reset your password.\"\n(CheckEmailForResetPasswordInstructions)\n\n\"An error occurred while sending the password reset email. Please try again later.\"\n(ErrorSendingResetPasswordEmail)\n\n\"Your account has been successfully updated!\"\n(AccountUpdatedSuccessfully)\n\n\"An error occurred while updating your account. Please try again later.\"\n(ErrorUpdatingAccount)",
