        "@id": "agent:OLLAMA-hf.co/s3nh/Unbabel-TowerInstruct-7B-v0.1-GGUF_Q4_K_M_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware began as a white paper written inside McGraw-Hill Education. It argued that GPS-enabled mobile devices would transform learning — that students walking through real places, guided by structured inquiry, could learn in a way textbooks never allowed."
    },
    {
      "@id": "entity:target-components_landingpage.peripateticware_began_as_a_white_paper_w-v1",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware הפך את העיצוב כספר בסבילה של מחבר מגרפי. זה נאמר בספר הביאופיה שלו, שהוא מתפרסם ב-McGraw-Hill Education. זה החל מכך שהתגובות GPS-enabled mobile devices (התקנות מובילות על טלפון) תוסף את המודרניזם החינם בתוך המודרניזם המושכים בספרים, ואף על פי כן שהאונלין יוכל ללמד בגון שהטקנות הספרים שלא היו כותבות זאת.",
      "generated_by": {
        "@id": "activity:translation-components_landingpage.peripateticware_began_as_a_white_paper_w-2026-06-23T07:40:51.882895+00:00"
      },
      "used_source": {
        "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w"
      }
    },
